    this.refill = refill
    this.per = per
    this.capacityScaled = capacity * per
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { tokensScaled: this.capacityScaled, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    if (tick > state.lastTick) {
      const delta = tick - state.lastTick
      const gained = this.refill * delta
      const next = state.tokensScaled + gained
      state.tokensScaled = next > this.capacityScaled ? this.capacityScaled : next
      state.lastTick = tick
    }
  }

