{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-x1q8mp/src/parser.js","content":"/**
 * Parses a limiter file into its declarations and events. Every failure
 * throws a `ParseError` naming the 1-based line number and the reason, so
 * the CLI can format `error: line N: <reason>` and stop at the first one.
 */
import { ParseError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

function parseUint(token) {
  if (!UINT_RE.test(token)) return null
  return BigInt(token)
}

/**
 * Parses text into `{ policies, routes, events }`, where `policies` maps a
 * name to its `TokenBucket` or `SlidingWindow` instance, `routes` is an
 * array of `{ prefix, policyNames }` in declaration order, and `events` is
 * an array of `{ tick, key }` in file order.
 */
export function parseInput(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let firstEventSeen = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const lineNumber = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const args = tokens.slice(1)

    const fail = (reason) => {
      throw new ParseError(lineNumber, reason)
    }

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (firstEventSeen) fail('declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (args.length !== 3) fail('expected bucket <name> <capacity> <refill> <per>')
      const [name, capacityTok, refillTok, perTok] = args
      if (!NAME_RE.test(name)) fail(`invalid policy name ${name}`)
      const capacity = parseUint(capacityTok)
      if (capacity === null || capacity < 1n) fail('capacity must be an integer of at least 1')
      const refill = parseUint(refillTok)
      if (refill === null || refill < 0n) fail('refill must be an integer of at least 0')
      const per = parseUint(perTok)
      if (per === null || per < 1n) fail('per must be an integer of at least 1')
      if (policies.has(name)) fail(`policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (args.length !== 2) fail('expected window <name> <limit> <span>')
      const [name, limitTok, spanTok] = args
      if (!NAME_RE.test(name)) fail(`invalid policy name ${name}`)
      const limit = parseUint(limitTok)
      if (limit === null || limit < 0n) fail('limit must be an integer of at least 0')
      const span = parseUint(spanTok)
      if (span === null || span < 1n) fail('span must be an integer of at least 1')
      if (policies.has(name)) fail(`policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (args.length < 1) fail('expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = args
      if (policyNames.length < 1) fail('expected route <prefix> <policy>...')
      if (!NAME_RE.test(prefix)) fail(`invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) fail(`prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) fail(`unknown policy ${name}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (args.length !== 2) fail('expected event <tick> <key>')
      const [tickTok, key] = args
      const tick = parseUint(tickTok)
      if (tick === null || tick < 0n) fail('tick must be an integer of at least 0')
      if (!NAME_RE.test(key)) fail(`invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      firstEventSeen = true
      events.push({ tick, key })
    } else {
      fail(`unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
