/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { parseInput } from './parser.js'
import { simulate } from './simulate.js'
import { ParseError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let parsed
  try {
    parsed = parseInput(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: line ${err.line}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { verdicts, perKey, total } = simulate(parsed)

  const out = []
  if (mode === 'replay') {
    for (const { tick, key, allowed, deniedBy } of verdicts) {
      out.push(allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${deniedBy}`)
    }
  } else {
    const keys = Array.from(perKey.keys()).sort()
    for (const key of keys) {
      const { allowed, denied } = perKey.get(key)
      out.push(`${key} allowed=${allowed} denied=${denied}`)
    }
    out.push(`total allowed=${total.allowed} denied=${total.denied}`)
  }

  const text = out.length > 0 ? out.join('\n') + '\n' : ''
  process.stdout.write(text)
  process.exit(0)
}

main()
"}

